def solve():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    for i in range(1, t + 1):
        s, c = input[i].split()
        if c in s and (len(s) - s.count(c)) % 2 == 0:
            print("YES")
        else:
            print("NO")

solve()
